const raw = $input.first().json.content.parts[0].text || '';
const cleaned = raw.replace(/```json|```/g, '').trim();
let d = {};
try { d = JSON.parse(cleaned); } catch (e) { d = { is_payment_receipt: false, description: raw }; }
const isReceipt = d.is_payment_receipt === true || d.is_payment_receipt === 'true';
return [{ json: { is_receipt: isReceipt, amount: d.amount || '', method: d.method || '', description: d.description || raw } }];

