const cq = $input.first().json.callback_query;
const parts = String(cq.data || '').split('|');
return [{ json: { action: parts[0], order_code: parts[1], query_id: cq.id, chat_id: cq.message && cq.message.chat ? cq.message.chat.id : '', from_name: (cq.from && cq.from.first_name) || '' } }];

const o = $('Get Order').first().json;
const lines = [];
lines.push('=== اوردر جديد ===');
lines.push('الوقت: ' + new Date().toLocaleString('en-GB', {timeZone: 'Africa/Cairo'}));
lines.push('------------------');
lines.push('رقم الاوردر: ' + o.order_code);
lines.push('العميل: ' + o.customer_name);
lines.push('الاوردر: ' + o.order_text);
lines.push('التمن: ' + o.total_price);
lines.push('العنوان: ' + o.address);
lines.push('التليفون: ' + o.phone);
lines.push('الدفع: ' + o.payment_method);
lines.push('------------------');
const text = lines.join('\n') + '\n\n\n';

const net = require('net');
await new Promise((resolve, reject) => {
  const client = new net.Socket();
  client.setTimeout(5000);
  client.once('error', reject);
  client.once('timeout', () => {
    client.destroy();
    reject(new Error('Printer timeout'));
  });
  client.connect(9100, 'host.docker.internal', () => {
    client.write(Buffer.from(text, 'utf8'), () => {
      client.end();
      resolve();
    });
  });
});

return [{ json: { printed: true } }];

