const now = Date.now();
const due = $input.all().filter(i => {
  const r = i.json;
  if (!r || !r.id || r.reminder_sent === true) return false;
  const t = r.awaiting_since ? new Date(r.awaiting_since).getTime() : NaN;
  return !isNaN(t) && (now - t) >= 5 * 60 * 1000;
});
return due;
